package com.primehr.security;
import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class RrEvaluationPermissionGuard{public static final String ELIGIBILITY="primehr.rr-eligibility",EVALUATION="primehr.rr-evaluation",AWARD="primehr.rr-award";private final AdministrativeAuthorizationClient client;public RrEvaluationPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public PermissionDataScope require(String feature,PrimeHrAction action,String token){var p=client.resolve(feature,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case EDIT->p.canEdit();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();case FINALIZE->p.canFinalize();default->false;};if(!allowed)throw new AccessDeniedException("Rewards and Recognition evaluation permission is required");var scope=p.administrator()?PermissionDataScope.AGENCY_WIDE:p.dataScope();if(scope!=PermissionDataScope.ASSIGNED_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Evaluation requires Assigned Records or Agency Wide scope");return scope;}}
